nge.App[nge.appNS].Tpl.Groups.UI_v3.Blue = {};
nge.App[nge.appNS].Tpl.Groups.UI_v3.Blue.BetSettings = function() {
    var a = nge.App[nge.appNS].Tpl.Groups.BetSettings();
    a.styles[".sliderMinMax"].style.fill = "#CBEBFF";
    a.styles[".settingName"].style.fill = "#FFFFFF";
    a.styles[".betContainerName"].style.fill = "#FFFFFF";
    a.styles[".betContainerValue"].style.fill = "#ffffff";
    a.styles[".sliderValue"].style.fill = "#FFFFFF";
    a.styles[".sliderTooltipValue"].style.fill = "#000000";
    return a
};
nge.App[nge.appNS].Tpl.Groups.UI_v3.Blue.ScrollbarVertical = function(a) {
    a = nge.App[nge.appNS].Tpl.Groups.ScrollbarVertical(a);
    var d = a.assets.contents.filter(function(a) {
        return -1 !== a.fullPath.indexOf("scroll_bg")
    })[0];
    d.fullPath = d.fullPath.replace("scroll_bg", "scroll_bg1");
    d = a.assets.contents.filter(function(a) {
        return -1 !== a.fullPath.indexOf("scroll_touch")
    })[0];
    d.fullPath = d.fullPath.replace("scroll_touch", "scroll_touch1");
    return a
};
nge.App[nge.appNS].Tpl.Groups.UI_v3.Blue.Tabs = function() {
    var a = nge.App[nge.appNS].Tpl.Groups.Tabs();
    a.styles["^headersContainer .active .tabHeaderText"].style.fill = "#0092E8";
    return a
};
nge.App[nge.appNS].Tpl.Groups.UI_v3.Blue.Ui = function() {
    var a = nge.App[nge.appNS].Tpl.Groups.UI_v3.Ui();
    a.styles[".autobuttonAmountTextBaseYellow"].style.fill = "#CAEAFF";
    a.styles[".autobuttonAmountTextBase"].style.fill = "#FFFFFF";
    a.styles[".buttonLinesText"].style.fill = "#CBEBFF";
    a.styles[".buttonLinesText"].style.stroke = "#00274A";
    a.styles[".freespinPlayedText"].style.fill = "#CAEAFF";
    a.styles[".linesNumber"].style.fill = "#FFFFFF";
    a.styles[".coinsNumber"].style.fill = "#FFFFFF";
    a.styles[".creditsTotalBetNumber"].style.fill =
        "#FFFFFF";
    a.styles[".totalBetNumber"].style.fill = "#FFFFFF";
    a.styles[".creditsNumber"].style.fill = "#FFFFFF";
    a.styles[".balanceNumber"].style.fill = "#FFFFFF";
    a.styles[".balanceCurrency"].style.fill = "#FFFFFF";
    a.styles[".winNumber"].style.fill = "#FFFFFF";
    a.styles[".creditsWinNumber"].style.fill = "#FFFFFF";
    return a
};
