        hP1Text1: "hP1Text1(text=IS WILD AND SUBSTITUTES\nFOR ALL SYMBOLS EXCEPT:, font=24pt futuricaextrablackitalic, anchorX=0.5, anchorY=0.5, align=center, fill=#fcf274, stroke=#000255, strokeThickness=2, maxWidth=565)_text",
        hP1Text2: "hP1Text2(text=EACH                         THAT SUBSTITUTES IN A LINE WIN\n \nMULTIPLIES THAT WIN BY            ., font=24pt futuricaextrablackitalic, anchorX=0.5, anchorY=0.5, align=center, fill=#fcf274, stroke=#000255, strokeThickness=2, maxWidth=1050)_text",
        hP1Text3: "hP1Text3(text=3X   , font=33pt futuricaextrablackitalic, fill=#39c0ff, stroke=#000255, strokeThickness=2)_text",
        hP1Text4: "hP1Text4(text=MORE THAN ONE MULTIPLIER\nMAY SUBSTITUTE ON A LINE WIN, UP  TO            ., font=24pt futuricaextrablackitalic, anchorX=0.5, anchorY=0.5, align=center, fill=#fcf274, stroke=#000255, strokeThickness=2)_text",
        hP1Text5: "hP1Text5(text=9X, font=33pt futuricaextrablackitalic, fill=#39c0ff, stroke=#000255, strokeThickness=2)_text",
