        hP1Text7: "hP1Text7(text=      , font=34pt futuricaextrablackitalic, fill=#39c0ff, stroke=#000255, strokeThickness=2)_text",
        hP2Text1: "hP2Text1(text=(color:#39c0ff)3 (color:#fcf274)BONUS SYMBOLS IN ANY POSITION\nIN THE BASE GAME\nPAY A SCATTER WIN OF (color:#39c0ff)1X (color:#fcf274)TOTAL BET\nAND TRIGGER (color:#39c0ff)7 (color:#fcf274)FREE GAMES., font=16pt futuricaextrablackitalic, anchorX=0.55, anchorY=0.2, align=center, fill=#fcf274, class=coloredText, stroke=#000255, strokeThickness=2)_text",
        hP2Text2: "hP2Text2(text=(color:#39c0ff)3(color:#fcf274) BONUS SYMBOL IN ANY POSITION\nDURING FREEGAMES\nPAY SCATTER WIN OF (color:#39c0ff)1X(color:#fcf274) TOTAL BET\nAND TRIGGER (color:#39c0ff)7(color:#fcf274) ADDITIONAL FREE\nGAMES UP TO A MAXIMUM OF (color:#39c0ff)700(color:#fcf274)., font=16pt futuricaextrablackitalic, anchorX=0.55, anchorY=0.5, align=center, fill=#fcf274, class=coloredText, stroke=#000255, strokeThickness=2)_text",
        hP2Text3: "hP2Text3(text=EACH FREE GAME TRIGGERS A\nSPITFIRE MULTIPLIER\nBETWEEN (color:#39c0ff)2X(color:#fcf274) AND (color:#39c0ff)7X(color:#fcf274)., font=16pt futuricaextrablackitalic, anchorX=0.5, anchorY=0.5, align=center, fill=#fcf274, class=coloredText, stroke=#000255, strokeThickness=2)_text",
        hP2Text4: "hP2Text4(text=WINS FOR THE CURRENT GAME ARE\nMULTIPLIED BY THE AWARDED CHILI\nMULTIPLIER, EXCEPT FOR:, font=16pt futuricaextrablackitalic, anchorX=0.5, anchorY=0.1, align=center, fill=#fcf274, stroke=#000255, strokeThickness=2)_text",
        hP3Text1: "hP3Text1(text=IN ACCORDANCE WITH FAIR GAMING\nPRACTICES REQUIRED IN MOST\nLEGAL JURISDICTIONS WORLDWIDE,\nEACH AND EVERY GAME OUTCOME IS\nCOMPLETELY INDEPENDENT. THE\nODDS OF GETTING ANY PARTICULAR\nOUTCOME ARE ALWAYS THE SAME., font=14pt futuricaextrablackitalic, fill=#fcf274, anchorX=0.07, anchorY=0.2, stroke=#000255, strokeThickness=2)_text",
        hP3Text2: "hP3Text2(text=THE ODDS DO NOT VARY BASED ON\nPRIOR OUTCOMES, BET SIZE,\nTIME OF DAY, DAY OF WEEK, ETC. FOR\nEXAMPLE, IF THE TOP AWARD IS WON\nON A SPIN ARE EXACTLYTHE SAME.\nLIKEWISE, PRIOR LOSSES DO NOT\nCHANGE FUTURE ODDS., font=14pt futuricaextrablackitalic, fill=#fcf274, anchorX=0.07, anchorY=0.1, stroke=#000255, strokeThickness=2)_text",
        hP3Text3: "hP3Text3(text=THE EXPECTED PAYBACK REFLECTS\nTHE THEORETICAL RETURN ACROSS A\nVERY LARGE NUMBER OF SPINS BY\nNUMEROUS PLAYERS OVER AN\n EXTENDED PERIOD OF TIME., font=14pt futuricaextrablackitalic, fill=#fcf274, anchorX=0.07, anchorY=0.0, stroke=#000255, strokeThickness=2)_text",
        hP3Text4: "hP3Text4(text=FOR THIS GAME, THE LONGTERM, THEO-\nRETICALLY EXPECTED PAYBACK IS\n92.01% TO 96.13%. THE RUSULT FOR\nANY GIVEN PLAYER OVER A PLAY SESSION\nCAN VARY WIDELY FROM THIS\nLONGTERM, EXPECTED AVERAGE IN\nEITHER DIRECTION. THE FEWER THE\nNUMBER OF GAMES PLAYED, THE WIDER\nTHE NORMAL VARIANCE OF ACTUAL\nPAYBACK MAY BE EXPERIENCE., font=14pt futuricaextrablackitalic, fill=#fcf274, anchorX=0.07, anchorY=0.1, stroke=#000255, strokeThickness=2)_text",
        hP3Text5: "hP3Text5(text=THE EXPECTED PAYBACK VALUE IS ALSO\nBASED UPON CORRECT PLAYER CHOICES\nFOR ANY GAMES WHICH INVOLVE\nMAIN GAME AND/OR BONUS GAME\nPLAY STRATEGY., font=14pt futuricaextrablackitalic, fill=#fcf274, anchorX=0.07, anchorY=0.1, stroke=#000255, strokeThickness=2)_text",
        hP3Text6: "hP3Text6(text=  , font=20pt futuricaextrablackitalic, fill=#fcf274, anchorX=0.5, anchorY=0.5, stroke=#000255, strokeThickness=2, align=center)_text",
